from __future__ import annotations


def revise_substantive_pairs(pairs: dict) -> dict:
    pairs["R2-1"] = (
        "我们讨论后采纳了同条件替代方案比较，并用实际变更记录补充维护评价。48条独立请求各重复五次，JSON对象、JSON模式、函数调用与增强解析器共享字段和验证规则；24条共同请求另有72份专家表单计划。混元三个接口的准确率为0.663、0.833和0.904，后两项相对JSON对象的Holm校正p值均小于0.001。增强解析器准确率0.771、执行就绪错误4、延迟0.10毫秒；专家表单处置准确率1.000。六项维护任务分别增加区域、时域、变量、权重、可靠性和报告的一个受控值，每项编辑一份共享声明，差异为两行新增、一行删除，并生成表单选项、解析词表和生成模式。六项共通过540次新增值检查，保留90项请求回归结果，原始与修改声明、差异及各接口测试均随复现材料提供。费用按四服务各自模型、缓存和在线报价计算。人工配对中，每服务265项可变输入最少需要替换70、96、116和140项，计数直接对应处置与明确字段。表格并列报告准确率、澄清、执行错误、延迟、token、服务费用及维护变更，使各接口的解释、录入与验证工作具有具体依据。",
        "We discussed and adopted matched alternative comparisons and added recorded changes to the maintenance evaluation. Each of 48 independent requests has five trials with JSON objects, JSON schema and function calling under shared fields and validation rules; the enhanced parser uses the same requirements, and 24 matched requests also have 72 expert-entered form plans. Hunyuan accuracy is 0.663, 0.833 and 0.904 for the three interfaces, with Holm-adjusted probabilities below 0.001 for the latter two against JSON objects. The enhanced parser has accuracy 0.771, four execution-readiness errors and latency 0.10 ms; expert forms have disposition accuracy 1.000. Six maintenance tasks each add one controlled value for region, horizon, variables, weight, reliability or reporting. Each edits one shared declaration, with two added and one removed line, and generates form choices, parser vocabulary and generation schema. The tasks pass 540 new-value checks and preserve 90 request regression outcomes. Original and revised declarations, differences and interface tests accompany the reproduction material. Fees use each service's model, cache and online tariff. In the expert-matched comparison, each service has 265 variable input entries requiring a minimum of 70, 96, 116 or 140 replacements, directly counted from dispositions and specified fields. The tables jointly report accuracy, clarification, execution errors, latency, tokens, service fees and maintenance changes, giving concrete evidence for interpretation, entry and validation work."
    )
    pairs["R2-3"] = (
        "我们同意重复调用、版本记录和服务费用应共同支撑比较。200条历史请求与48条独立请求按每服务五次形成4960个主试次，固定温度0、top-p 1、4096输出token及120秒超时。历史联合成功率为0.772、0.751、0.703和0.661，聚类区间和六组Holm校正p值0.346—0.938完整报告。调用日期、模型、端点、提示、解码、响应、token和延迟逐条归档。费用采用各服务实际返回模型的官方在线价格，结合缓存token和适用计费时段；每项240次独立请求试次的报价估算为DeepSeek 0.082259美元、千问0.946202元、ERNIE 0.491117元、混元2.597703元，平均每次分别为0.000343美元、0.003943元、0.002046元和0.010824元。价格页快照、哈希及逐试次计算保存在复现包，标准报价与账户结算条件明确对应。六字段扩展的300条初始响应和60条确认响应采用单独协议记录，用于完整字段到计算的补充评价。",
        "We agree that repeated calls, version records and service fees should jointly support comparison. Two hundred historical and 48 independent requests, with five trials per service, give 4,960 primary trials at temperature 0, top-p 1, a 4,096-output-token limit and a 120-second timeout. Historical joint success is 0.772, 0.751, 0.703 and 0.661; clustered intervals and six Holm-adjusted probabilities of 0.346 to 0.938 are fully reported. Dates, models, endpoints, prompts, decoding, responses, tokens and latency are archived per trial. Fees use the official online tariff for each returned model, recorded cache tokens and the applicable billing period. For 240 independent-request trials per service, list-price estimates total 0.082259 USD for DeepSeek and 0.946202, 0.491117 and 2.597703 CNY for Qwen, ERNIE and Hunyuan. Mean fees are 0.000343 USD and 0.003943, 0.002046 and 0.010824 CNY. Price snapshots, hashes and trial-level arithmetic accompany the reproduction package, with standard tariffs linked to their account settlement conditions. The six-field extension separately archives 300 initial and 60 confirmation responses under its own protocol for field-to-calculation evaluation."
    )
    pairs["R2-7"] = (
        "我们同意应使六类请求字段都进入实际计算，并按计划结果量化准备资源与数值后果。原22条独立请求的440次重放直接传递区域、时域和缺额权重。我们另设计了十五条六字段扩展请求，包含九条完整规格、三条字段缺省和三条信息或授权边界情形，每服务各重复五次，保存300条初始响应及60条字段确认响应。完整请求的离线执行数分别为45/45、45/45、17/45和42/45，确认后执行为11/15、10/15、11/15和15/15。合计196份计算输出与各自参考备用和成本一致，九条规格每条都有至少十三次实际执行，变量、可靠性与报告也直接读取服务计划。报告字段实际增加所要求的尾部缺额结果，并保留相同备用序列。正确接受、不完整返回、错误返回、澄清和边界请求分别列出服务时间、字段替换、各供应商报价费用和计算阶段；澄清包含一次字段确认的资源。为量化明确字段错误的后果，我们在实际接受响应中逐项注入六类单字段偏差，95项全部返回确认。区域偏差的潜在覆盖为0.430、成本差为+0.101534；时域、变量、权重和可靠性偏差的成本差为+0.002925、+0.000285、+0.001176和+0.000734。报告遗漏对应所需尾部结果缺失。自然服务结果与受控偏差各自保留来源、分母和哈希，数值费用与准备资源按其单位分别评价。",
        "We agree that all six requested field categories should enter actual calculations, with preparation resources and numerical consequences reported by plan outcome. The original 440 replays for 22 independent requests transfer region, horizon and shortfall weight directly. We also designed fifteen requests for a separate six-field extension: nine complete specifications, three omissions and three information or authorization boundary conditions. Five trials per request and service preserve 300 initial and 60 field-confirmation responses. Complete-request offline executions are 45/45, 45/45, 17/45 and 42/45; after confirmation they are 11/15, 10/15, 11/15 and 15/15. All 196 numerical outputs match their request-specific reserve and cost reference. Every complete specification has at least thirteen actual executions, and variables, reliability and reporting are read directly from service plans. Reporting adds the requested tail-shortfall result while preserving the reserve sequence. Correct accepted, incomplete returned, incorrect returned, clarified and boundary plans each have service time, field replacements, provider-specific list-price fees and calculation stage; clarification includes its field-confirmation resources. To quantify explicit field-error consequences, we inject six categories of single-field deviation into actual accepted responses. All 95 return for confirmation. The region deviation has potential coverage 0.430 and cost difference +0.101534; horizon, variable, weight and reliability deviations have differences +0.002925, +0.000285, +0.001176 and +0.000734. The report omission removes the required tail result. Natural service outcomes and controlled deviations retain separate provenance, denominators and hashes, with numerical costs and preparation resources evaluated in their respective units."
    )
    pairs["R3-5"] = (
        "我们采纳了同请求专家配对比较，并以实际计划内容量化输入工作量。三位专家对24条共同请求准备72份计划，处置准确率均1.000，字段准确率1.000、1.000和0.825，自估平均准备时间2.93—3.25分钟；四服务各120次配对响应保留字段、处置及执行就绪结果。将每份计划的处置和明确区域、时域、缺额权重作为可变输入，每服务共有265项，固定备用权重由协议提供。按专家参考更正，最少替换量为70、96、116和140项，保留195、169、149和125项参考正确内容，所需录入量减少73.6%、63.8%、56.2%和47.2%。该指标计算参考所需的输入操作，人工核查涵盖全部处置与字段。原200项字段对照和50、91、81、122项修正数量同时保留。时间评价采用每请求专家平均自估时间减去实测服务延迟，复核阈值中位数为175.4、170.3、160.6和155.6秒；复核耗时低于对应阈值时，服务与复核的总时间低于专家自估参照。Noy与Zhang的453人随机写作实验及Vaccaro等106项研究、370个效应量提供按任务评价协作的方法背景。本文据此直接呈现专家质量、可复用草稿内容、录入替换量、实测服务延迟与条件复核阈值。",
        "We adopted the expert comparison on matched requests and quantified input work from the actual plans. Three experts prepare 72 plans for the same 24 requests. Their disposition accuracy is 1.000 each, field accuracy is 1.000, 1.000 and 0.825, and mean self-estimated preparation time is 2.93 to 3.25 minutes. Each service has 120 matched responses with retained field, disposition and readiness results. Counting the disposition and specified region, horizon and shortfall weight gives 265 variable entries per service; the protocol supplies the fixed reserve weight. Reference correction requires a minimum of 70, 96, 116 and 140 replacements, retaining 195, 169, 149 and 125 reference-correct entries. Required data entry therefore decreases by 73.6%, 63.8%, 56.2% and 47.2%. This metric counts input operations required by the reference, with human verification covering all dispositions and fields. The original 200-field comparison and its 50, 91, 81 and 122 corrections are also retained. Time evaluation subtracts measured service latency from the request-specific mean expert estimate, giving median review thresholds of 175.4, 170.3, 160.6 and 155.6 seconds. Review below its corresponding threshold places service-plus-review time below the expert self-estimated reference. The 453-person randomized writing study by Noy and Zhang and the synthesis of 106 studies and 370 effects by Vaccaro et al. provide methodological context for task-specific collaboration evaluation. Our results directly present expert quality, reusable draft content, input replacements, measured service latency and conditional review thresholds."
    )
    for key in ("R3-2", "R3-3", "R3-8", "R3-16"):
        chinese, english = pairs[key]
        if key in ("R3-2", "R3-3"):
            chinese += "六字段扩展另外归档300条初始和60条确认响应，关联其独立协议、模型设置、日期、请求与返回、费用和数值输出。"
            english += " The six-field extension separately archives 300 initial and 60 confirmation responses, linked to its protocol, model settings, dates, requests and returns, fees and numerical outputs."
        elif key == "R3-8":
            chinese += "六字段实际响应扩展另有196份离线计算输出，九条完整规格均有实际执行；95项单字段注入偏差全部返回确认，对应数值或报告后果。"
            english += " The actual-response six-field extension adds 196 offline numerical outputs, with actual execution for all nine complete specifications. All 95 single-field injected deviations return for confirmation, linked to numerical or report consequences."
        else:
            chinese += "六字段扩展的196份实际服务计划计算输出、95项字段偏差检查及265项可变输入的替换量进一步对应这一研究准备范围。"
            english += " The six-field extension's 196 computations from actual service plans, 95 field-deviation checks and replacement counts for 265 variable input entries further support this study-preparation scope."
        pairs[key] = chinese, english
    return pairs
